/* @lc app=leetcode id=1958 lang=kotlin */
class Solution { fun checkMove(board: Array<CharArray>, rMove: Int, cMove: Int, color: Char): Boolean = listOf(-1 to -1, -1 to 0, -1 to 1, 0 to -1, 0 to 1, 1 to -1, 1 to 0, 1 to 1).any { (dr, dc) -> (1..7).firstOrNull { k -> (rMove + k * dr).let { r -> (cMove + k * dc).let { c -> r !in 0..7 || c !in 0..7 || board[r][c] == '.' || board[r][c] == color } } }?.let { k -> (rMove + k * dr).let { r -> (cMove + k * dc).let { c -> k >= 2 && r in 0..7 && c in 0..7 && board[r][c] == color } } } ?: false } }